import heapq

def match(orders):
    buy_heap = []   # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    book = {}       # id -> [side, price, qty, seq, active]
    seq = 0
    trades = []

    def pop_invalid(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            info = book.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(heap)
            else:
                return top
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None:
                info[4] = False
            continue

        if typ == 'limit' or typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq += 1
        remaining = qty

        if side == 'buy':
            opp = sell_heap
        else:
            opp = buy_heap

        while remaining > 0:
            top = pop_invalid(opp)
            if top is None:
                break
            oid_match = top[2]
            info = book[oid_match]
            resting_price = info[1]

            if typ == 'market':
                can_match = True
            else:
                if side == 'buy':
                    can_match = price >= resting_price
                else:
                    can_match = price <= resting_price

            if not can_match:
                break

            trade_qty = min(remaining, info[2])
            if side == 'buy':
                trades.append([oid, oid_match, resting_price, trade_qty])
            else:
                trades.append([oid_match, oid, resting_price, trade_qty])

            remaining -= trade_qty
            info[2] -= trade_qty

            if info[2] <= 0:
                info[4] = False
                heapq.heappop(opp)

        if typ == 'limit' and remaining > 0:
            book[oid] = [side, price, remaining, seq, True]
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

